import json, re
from pathlib import Path

ROOT=Path(__file__).parent
original=Path('/Users/macbookprom1/Downloads/Мастерская в Эль-Больсоне.html').read_text()
source=original.split('var STAGES = [',1)[1].split('/* ---------- helpers',1)[0]
catalog=[]
for block in re.split(r"(?=\{key:')",source)[1:]:
    stage=re.search(r"key:'([^']+)'",block).group(1)
    for line in block.split('items:[',1)[1].split('goals:',1)[0].splitlines():
        if not re.search(r"\{id:'",line): continue
        def string(key):
            m=re.search(r"\b"+key+r":'((?:\\.|[^'\\])*)'",line)
            return m.group(1).replace("\\'","'") if m else ''
        ident=string('id')
        catalog.append({'id':ident,'title':string('t'),'note':string('n'),'oldStage':stage,
          'kind':'have' if "k:['have']" in line else ('diy' if "'diy'" in re.search(r'k:\[([^]]*)\]',line).group(0) else 'buy'),
          'optional':'opt:true' in line or stage=='later','quote':None})

