TASKS=[]
def task(id,module,title,hours,deps=(),result='',items=(),lag=0,gate='',project=''):
    TASKS.append(dict(id=id,module=module,title=title,hours=hours,deps=list(deps),result=result,
       items=list(items),lag=lag,gate=gate,project=project))

